from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ends = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ends[b].append((a, i))

        largest = 0
        second = 0
        largest_id = -1
        total = 0
        gains = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for left, pair_id in ends[right]:
                if left >= largest:
                    second = largest
                    largest = left
                    largest_id = pair_id
                elif left > second:
                    second = left

            total += right - largest
            if largest_id != -1:
                gains[largest_id] += largest - second

        return total + max(gains)

