def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = []
    for _ in range(m):
        a = next(it) - 1
        b = next(it) - 1
        c = next(it)
        edges.append((a, b, c))

    queries = []
    deleted = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            queries.append((1, e))
            deleted[e] = True
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not deleted[i]:
            dist[a][b] = c
            dist[b][a] = c

    # All-pairs shortest paths in the graph remaining after every query.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            row_i = dist[i]
            dik = row_i[k]
            if dik == INF:
                continue
            for j in range(n):
                val = dik + row_k[j]
                if val < row_i[j]:
                    row_i[j] = val

    answers = []
    # Reverse time: a closure becomes an edge insertion.
    for query in reversed(queries):
        if query[0] == 2:
            x, y = query[1], query[2]
            value = dist[x][y]
            answers.append(str(value if value < INF else -1))
        else:
            u, v, w = edges[query[1]]
            row_u = dist[u]
            row_v = dist[v]
            for i in range(n):
                row_i = dist[i]
                diu = row_i[u]
                div = row_i[v]
                if diu == INF and div == INF:
                    continue
                for j in range(n):
                    best = row_i[j]
                    if diu != INF:
                        value = diu + w + row_v[j]
                        if value < best:
                            best = value
                    if div != INF:
                        value = div + w + row_u[j]
                        if value < best:
                            best = value
                    row_i[j] = best

    sys.stdout.write('\n'.join(reversed(answers)))

