def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; a=data[1:]
    pref=[0]*(n+1); seen=set()
    for i,x in enumerate(a,1):
        seen.add(x); pref[i]=len(seen)
    suff=[0]*(n+2); seen.clear()
    for i in range(n,0,-1):
        seen.add(a[i-1]); suff[i]=len(seen)
    size=1
    while size<n+2:size*=2
    neg=-10**9
    seg=[neg]*(2*size); lazy=[0]*(2*size)
    for i in range(1,n): seg[size+i]=pref[i]
    for p in range(size-1,0,-1):seg[p]=max(seg[2*p],seg[2*p+1])
    def apply(p,v):seg[p]+=v;lazy[p]+=v
    def push(p):
        if lazy[p]:
            v=lazy[p];apply(2*p,v);apply(2*p+1,v);lazy[p]=0
    def add(p,l,r,ql,qr,v):
        if ql<=l and r<=qr: apply(p,v);return
        push(p);m=(l+r)//2
        if ql<=m:add(2*p,l,m,ql,qr,v)
        if qr>m:add(2*p+1,m+1,r,ql,qr,v)
        seg[p]=max(seg[2*p],seg[2*p+1])
    def setv(p,l,r,x,v):
        if l==r:seg[p]=v;lazy[p]=0;return
        push(p);m=(l+r)//2
        if x<=m:setv(2*p,l,m,x,v)
        else:setv(2*p+1,m+1,r,x,v)
        seg[p]=max(seg[2*p],seg[2*p+1])
    last=[0]*(n+1); ans=0
    for j in range(2,n):
        x=a[j-1]; l=max(1,last[x])
        add(1,1,size,l,j-1,1)
        setv(1,1,size,j-1,pref[j-1]+1)
        ans=max(ans,seg[1]+suff[j+1])
        last[x]=j
    # Need last updates for occurrences before j!
    print(ans)
