import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    items = []
    upper = 10**30
    for i in range(n):
        a, p, b, q = data[2 + 4*i: 6 + 4*i]
        items.append((a, p, b, q))
        # A process cannot produce more than its best capacity-per-yen rate.
        upper = min(upper, max(budget * a // p, budget * b // q) + 1)

    def feasible(target):
        total = 0
        for a, p, b, q in items:
            best = 10**30
            if p * b <= q * a:
                # S has no worse cost per unit of capacity.  An optimum
                # needs fewer than a T machines.
                for t in range(a):
                    remaining = target - b * t
                    s = 0 if remaining <= 0 else (remaining + a - 1) // a
                    cost = s * p + t * q
                    if cost < best:
                        best = cost
            else:
                # Symmetric case: an optimum needs fewer than b S machines.
                for s in range(b):
                    remaining = target - a * s
                    t = 0 if remaining <= 0 else (remaining + b - 1) // b
                    cost = s * p + t * q
                    if cost < best:
                        best = cost
            total += best
            if total > budget:
                return False
        return True

    low = 0
    while upper - low > 1:
        mid = (low + upper) // 2
        if feasible(mid):
            low = mid
        else:
            upper = mid
    print(low)

if __name__ == "__main__":
    solve()

