import sys

def bad(a,b):
    l,r,d=a; x,y,e=b
    # normalize ordering already
    if r < x or y < l:
        return False
    # nested or endpoint-touching overlap
    if (l <= x and y <= r) or (x <= l and r <= y):
        return True
    # proper crossing: l < x < r < y
    return d == e

