def main():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    inc = [[[] for _ in range(26)] for _ in range(n)]
    INF = 10**9
    dist = [[INF] * n for _ in range(n)]
    left = n * n
    maxdist = 0
    heap = []

    for i in range(n):
        dist[i][i] = 0
        left -= 1
        heapq.heappush(heap, (0, i, i))
        for j, ch in enumerate(g[i]):
            if ch != '-':
                k = ord(ch) - 97
                out[i][k].append(j)
                inc[j][k].append(i)
                if dist[i][j] > 1:
                    if dist[i][j] == INF:
                        left -= 1
                    dist[i][j] = 1
                    maxdist = 1
                    heapq.heappush(heap, (1, i, j))

    while heap:
        d, x, y = heapq.heappop(heap)
        if d != dist[x][y]:
            continue
        nd = d + 2
        if left == 0 and nd >= maxdist:
            continue
        for k in range(26):
            incoming = inc[x][k]
            outgoing = out[y][k]
            for u in incoming:
                row = dist[u]
                for v in outgoing:
                    if nd < row[v]:
                        if row[v] == INF:
                            left -= 1
                        row[v] = nd
                        if nd > maxdist:
                            maxdist = nd
                        heapq.heappush(heap, (nd, u, v))

    for row in dist:
        print(*(-1 if value == INF else value for value in row))

