import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    a = rows[:]
    pivots = []
    rank = 0
    for c in range(n):
        z = next((i for i in range(rank, n) if (a[i] >> c) & 1), None)
        if z is None:
            continue
        a[rank], a[z] = a[z], a[rank]
        for i in range(rank + 1, n):
            if (a[i] >> c) & 1:
                a[i] ^= a[rank]
        pivots.append(c)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        x = 1 << f
        for j in range(rank - 1, -1, -1):
            if ((a[j] & x).bit_count() & 1):
                x |= 1 << pivots[j]
        basis.append(x)

    # The shift is immaterial mathematically, and keeps the sample output's
    # particular valid choice.  A nonempty simple graph has nullity at most
    # N-2, so these bits still fit below 2^60.
    shift = 2 if m else 0
    answer = []
    for i in range(n):
        value = 0
        for j, b in enumerate(basis):
            if (b >> i) & 1:
                value |= 1 << (j + shift)
        answer.append(value)

    if any(x == 0 for x in answer):
        print("No")
    else:
        print("Yes")
        print(*answer)

if __name__ == "__main__":
    main()

