from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = min(CAP, factorial[i - 1] * i)

        odd = sum(i & 1 for i in range(1, n + 1))
        even = n - odd
        used = [False] * (n + 1)
        answer = []
        required = None  # parity required for the next element, or None initially

        def completions(o: int, e: int, first_parity: int) -> int:
            length = o + e
            if first_parity == 1:
                if o != (length + 1) // 2 or e != length // 2:
                    return 0
            else:
                if e != (length + 1) // 2 or o != length // 2:
                    return 0
            return min(CAP, factorial[o] * factorial[e])

        for position in range(n):
            for value in range(1, n + 1):
                parity = value & 1
                if used[value] or (required is not None and parity != required):
                    continue

                new_odd = odd - parity
                new_even = even - (parity == 0)
                if position == n - 1:
                    count = 1
                else:
                    count = completions(new_odd, new_even, 1 - parity)

                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    used[value] = True
                    odd, even = new_odd, new_even
                    required = 1 - parity
                    break
            else:
                return []

        return answer

