class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        total = m * n

        fact = [1] * (total + 1)
        for i in range(1, total + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (total + 1)
        inv_fact[total] = pow(fact[total], MOD - 2, MOD)
        for i in range(total, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        arrangements_with_pair = (
            fact[total - 2] * inv_fact[k - 2] % MOD * inv_fact[total - k] % MOD
        )

        row_distance_sum = m * (m - 1) * (m + 1) // 6
        column_distance_sum = n * (n - 1) * (n + 1) // 6
        all_pair_distances = (
            n * n * row_distance_sum + m * m * column_distance_sum
        ) % MOD

