class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # Coefficient of each independently chosen digit in the palindrome.
        power = [1] * n
        for e in range(1, n):
            power[e] = power[e - 1] * 10 % k
        coeff = [0] * half
        for i in range(half):
            c = power[n - 1 - i]
            if n - 1 - i != i:
                c = (c + power[i]) % k
            coeff[i] = c

        # suffix[i] is a bitset of residues attainable by positions i onward.
        full = (1 << k) - 1
        suffix = [0] * (half + 1)
        suffix[half] = 1  # residue zero
        for i in range(half - 1, -1, -1):
            c = coeff[i]
            base = suffix[i + 1]
            possible = 0
            for digit in range(10):
                shift = (digit * c) % k
                if shift == 0:
                    possible |= base
                else:
                    possible |= ((base << shift) | (base >> (k - shift))) & full
            suffix[i] = possible

        # Greedily choose the largest digit whose suffix can complete residue 0.
        residue = 0
        left = []
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-residue - digit * c) % k
                if (suffix[i + 1] >> needed) & 1:
                    left.append(str(digit))
                    residue = (residue + digit * c) % k
                    break

        first_half = ''.join(left)
        if n % 2:
            return first_half + first_half[-2::-1]
        return first_half + first_half[::-1]

