from typing import List
from array import array

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # nxt[i] is the first position to the right whose value is larger.
        nxt = [n] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                nxt[stack.pop()] = i
            stack.append(i)

        levels = n.bit_length()
        jumps = [array('i', [n]) * n]
        sums = [array('q', [0]) * n]
        ju, su = jumps[0], sums[0]
        for i in range(n):
            q = nxt[i]
            ju[i] = q
            if q < n:
                # Contribution of nums[i] until the next larger element.
                su[i] = nums[i] * (q - i)

        for _ in range(1, levels):
            pju, psu = jumps[-1], sums[-1]
            ju = array('i', [n]) * n
            su = array('q', [0]) * n
            for i in range(n):
                mid = pju[i]
                if mid < n:
                    ju[i] = pju[mid]
                    su[i] = psu[i] + psu[mid]
                else:
                    ju[i] = n
                    su[i] = psu[i]
            jumps.append(ju)
            sums.append(su)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def cost(left, right):
            # Sum of the prefix maxima on [left, right], minus the elements.
            node = left
            max_sum = 0
            for z in range(levels - 1, -1, -1):
                q = jumps[z][node]
                if q <= right:
                    max_sum += sums[z][node]
                    node = q
            max_sum += nums[node] * (right - node + 1)
            return max_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for right in range(n):
            lo, hi = 0, right + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

