from typing import List
from array import array

class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        table = array('I', [0]) * (n * n)

        for i, value in enumerate(nums):
            table[i * n + i] = value

        # score[l][r] = score[l][r-1] XOR score[l+1][r]
        for length in range(2, n + 1):
            for left in range(n - length + 1):
                right = left + length - 1
                table[left * n + right] = (
                    table[left * n + right - 1]
                    ^ table[(left + 1) * n + right]
                )

        # Replace each score by the maximum score of any subarray in its interval.
        for length in range(2, n + 1):
            for left in range(n - length + 1):
                right = left + length - 1
                best = table[left * n + right]
                candidate = table[left * n + right - 1]
                if candidate > best:
                    best = candidate
                candidate = table[(left + 1) * n + right]
                if candidate > best:
                    best = candidate
                table[left * n + right] = best

        return [table[left * n + right] for left, right in queries]

