from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first = p.find('*')
        second = p.find('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])

        def occurrences(word):
            m = len(word)
            if m == 0:
                return range(n + 1)

            prefix = [0] * m
            k = 0
            for i in range(1, m):
                while k and word[i] != word[k]:
                    k = prefix[k - 1]
                if word[i] == word[k]:
                    k += 1
                prefix[i] = k

            result = []
            k = 0
            for i, ch in enumerate(s):
                while k and ch != word[k]:
                    k = prefix[k - 1]
                if ch == word[k]:
                    k += 1
                if k == m:
                    result.append(i - m + 1)
                    k = prefix[k - 1]
            return result

        starts_a, starts_b, starts_c = (occurrences(x) for x in parts)
        len_a, len_b, len_c = map(len, parts)
        best = n + 1

        for start_a in starts_a:
            ib = bisect_left(starts_b, start_a + len_a)
            if ib == len(starts_b):
                continue
            start_b = starts_b[ib]
            ic = bisect_left(starts_c, start_b + len_b)
            if ic == len(starts_c):
                continue
            start_c = starts_c[ic]
            best = min(best, start_c + len_c - start_a)

        return -1 if best == n + 1 else best

