import sys

def minimum(a, b):
    xs = [i for i, c in enumerate(a) if c == '1']
    ys = [i for i, c in enumerate(b) if c == '1']
    k, m = len(xs), len(ys)
    if k < m:
        return -1

    def possible(d):
        lo = hi = 0
        left = right = 0
        for t in ys:
            while left < k and xs[left] < t - d:
                left += 1
            if right < left:
                right = left
            while right < k and xs[right] <= t + d:
                right += 1
            # The current group starts at some boundary s in [lo,hi],
            # and must cover a nonempty interval within [left,right).
            if lo >= right or hi < left:
                return False
            nlo = max(lo, left + 1)
            nhi = right
            if nlo > nhi:
                return False
            lo, hi = nlo, nhi
        return lo <= k <= hi

    low, high = 0, len(a)
    while low < high:
        mid = (low + high) // 2
        if possible(mid):
            high = mid
        else:
            low = mid + 1
    return low

def main():
    data = sys.stdin.buffer.read().split()
