import sys
from collections import deque

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n,m,s,t=data[:4]; s-=1;t-=1
    g=[[] for _ in range(n)]
    k=4
    for _ in range(m):
        a=data[k]-1;b=data[k+1]-1;k+=2
        g[a].append(b);g[b].append(a)
    def bfs(st):
        d=[-1]*n;d[st]=0;q=deque([st])
        while q:
            v=q.popleft()
            for w in g[v]:
                if d[w]<0:d[w]=d[v]+1;q.append(w)
        return d
    ds=bfs(s); dt=bfs(t); D=ds[t]
    if n==2:
        print(-1);return
    # A direct shortest-path pair gives the 2D optimum. Find two paths by
    # augmenting in the shortest-path DAG (vertex capacity one internally).
    # For two units, a simple residual search is sufficient.
    adj=[[] for _ in range(n)]
    for v in range(n):
        if ds[v]>=0 and ds[v]+dt[v]==D:
            for w in g[v]:
                if ds[w]==ds[v]+1 and ds[w]+dt[w]==D:
                    adj[v].append(w)
    # vertex-disjoint paths: augment once, then use residual graph
    # represented explicitly with vertex splitting
    N=2*n; E=[[] for _ in range(N)]
    def add(a,b,c): E[a].append([b,c,len(E[b])]);E[b].append([a,0,len(E[a])-1])
    for v in range(n):
        if ds[v]+dt[v]==D:
            add(2*v,2*v+1,2 if v in (s,t) else 1)
    for v in range(n):
        for w in adj[v]: add(2*v+1,2*w,2)
    src=2*s; sink=2*t+1; flow=0
    while flow<2:
        par=[None]*N;q=deque([src]);par[src]=(-1,-1)
        while q and par[sink] is None:
            v=q.popleft()
            for i,e in enumerate(E[v]):
                if e[1] and par[e[0]] is None:par[e[0]]=(v,i);q.append(e[0])
        if par[sink] is None:break
        flow+=1;v=sink
        while v!=src:
            u,i=par[v];e=E[u][i];e[1]-=1;E[v][e[2]][1]+=1;v=u
    if flow==2: print(2*D);return
    # With one usable route, one extra move suffices whenever there is a
    # spare vertex; the sole path graph has no legal initial detour.
    if n==D+1 and m==n-1:
        print(-1)
    else:
        print(2*D+1)
