class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        for _ in range(t):
            next_counts = [0] * 26
            for i, amount in enumerate(counts):
                if i == 25:
                    next_counts[0] = (next_counts[0] + amount) % MOD
                    next_counts[1] = (next_counts[1] + amount) % MOD
                else:
                    next_counts[i + 1] = (next_counts[i + 1] + amount) % MOD
            counts = next_counts

        return sum(counts) % MOD

