class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        slopes = [None] * (4 * n)
        intercepts = [0] * (4 * n)

        def add_line(node, left, right, slope, intercept):
            if slopes[node] is None:
                slopes[node] = slope
                intercepts[node] = intercept
                return

            mid = (left + right) // 2
            old_slope = slopes[node]
            old_intercept = intercepts[node]

            if slope * mid + intercept > old_slope * mid + old_intercept:
                slopes[node], slope = slope, old_slope
                intercepts[node], intercept = intercept, old_intercept

            if left == right:
                return

            if slope * left + intercept > slopes[node] * left + intercepts[node]:
                add_line(node * 2, left, mid, slope, intercept)
            elif slope * right + intercept > slopes[node] * right + intercepts[node]:
                add_line(node * 2 + 1, mid + 1, right, slope, intercept)

        def query(node, left, right, x):
            if slopes[node] is None:
                return -10**30

            result = slopes[node] * x + intercepts[node]
            if left == right:
                return result

            mid = (left + right) // 2
            if x <= mid:
                return max(result, query(node * 2, left, mid, x))
            return max(result, query(node * 2 + 1, mid + 1, right, x))

        add_line(1, 0, n - 1, nums[0], 0)
        answer = 0
        for i in range(1, n):
            best = query(1, 0, n - 1, i)
            answer = best
            add_line(1, 0, n - 1, nums[i], best - i * nums[i])

        return answer

