import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        lower = 10 ** (digits - 1)
        upper = 10 ** digits - 1

        prime = bytearray(b'\x01') * (upper + 1)
        prime[0] = 0
        if upper >= 1:
            prime[1] = 0
        p = 2
        while p * p <= upper:
            if prime[p]:
                prime[p * p:upper + 1:p] = b'\x00' * (((upper - p * p) // p) + 1)
            p += 1

        if prime[n] or prime[m]:
            return -1

        inf = 10 ** 30
        dist = [inf] * (upper + 1)
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            text = str(value)
            for pos, ch in enumerate(text):
                digit = ord(ch) - 48
                for change in (-1, 1):
                    new_digit = digit + change
                    if not (0 <= new_digit <= 9):
                        continue
                    # Intermediate values retain the common digit length.
                    if pos == 0 and new_digit == 0:
                        continue
                    next_value = int(text[:pos] + str(new_digit) + text[pos + 1:])
                    if prime[next_value]:
                        continue
                    next_cost = cost + next_value
                    if next_cost < dist[next_value]:
                        dist[next_value] = next_cost
                        heapq.heappush(heap, (next_cost, next_value))

        return -1

