from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        def z_array(start):
            m = n - start
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k < right:
                    z[k] = min(right - k, z[k - left])
                while (k + z[k] < m and
                       nums[start + z[k]] == nums[start + k + z[k]]):
                    z[k] += 1
                if k + z[k] > right:
                    left, right = k, k + z[k]
            return z

        # z0[a] is the LCP of nums and nums[a:].
        z0 = z_array(0)
        answer = 0

        # a is the end of the first part; d is the length of the second.
        for a in range(1, n - 1):
            first_is_prefix = z0[a] >= a
            z = z_array(a)
            for d in range(1, n - a):
                # The second condition compares nums[a:a+d] with nums[a+d:].
                if (first_is_prefix and d >= a) or z[d] >= d:
                    answer += 1
        return answer

