class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        is_target = [False] * len(source)
        for i in targetIndices:
            is_target[i] = True

        inf = m + 1
        # dp[j] is the minimum number of target characters used to
        # form pattern[:j] from the source processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = 1 if is_target[i] else 0
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] < inf:
                    candidate = dp[j] + cost
                    if candidate < dp[j + 1]:
                        dp[j + 1] = candidate

        # Every target index not used by the chosen embedding can be removed.
        return len(targetIndices) - dp[m]

