class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse the edges: reaching every node from 0 in this graph is
        # equivalent to every node being able to reach 0 in the original.
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        inf = 10**18
        best = [inf] * n
        best[0] = 0
        heap = [(0, 0)]

        while heap:
            cur, u = heapq.heappop(heap)
            if cur != best[u]:
                continue
            for v, w in rev[u]:
                candidate = max(cur, w)
                if candidate < best[v]:
                    best[v] = candidate
                    heapq.heappush(heap, (candidate, v))

