from bisect import bisect_right

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        n = len(word)

        # pref[i] is the number of consonants before position i.
        pref = [0] * (n + 1)
        for i, ch in enumerate(word):
            pref[i + 1] = pref[i] + (ch not in vowels)

        # For each consonant-prefix value, retain all start positions having it.
        positions = {}
        for i, value in enumerate(pref):
            positions.setdefault(value, []).append(i)

        last = {ch: -1 for ch in vowels}
        answer = 0
        for right, ch in enumerate(word):
            if ch in vowels:
                last[ch] = right

            # A start must be no later than this to include every vowel.
            latest_start = min(last.values())
            if latest_start < 0:
                continue

            needed = pref[right + 1] - k
            starts = positions.get(needed)
            if starts is not None:
                answer += bisect_right(starts, latest_start)

        return answer

